// ============================================================
// NODE: Trigger Normalizer — Islamic Shorts / Kling-1.5 / 15-20s
// ============================================================

const TIMEZONE_OFFSET_HOURS = 3;
const PUBLISH_HOUR = 21;

const nowUtc = new Date();
const local  = new Date(nowUtc.getTime() + TIMEZONE_OFFSET_HOURS * 3600000);
const yyyy   = local.getUTCFullYear();
const mm     = String(local.getUTCMonth() + 1).padStart(2, '0');
const dd     = String(local.getUTCDate()).padStart(2, '0');
const localDate = `${yyyy}-${mm}-${dd}`;
const localHour = local.getUTCHours();

const EPOCH    = Date.UTC(2024, 0, 1);
const dayIndex = Math.floor(
  (Date.UTC(yyyy, local.getUTCMonth(), local.getUTCDate()) - EPOCH) / 86400000
);

const ISLAMIC_CATEGORIES = [
  'tamal_qurani','tamal_kawni','muraqabat_nafs','ilm_wa_marifa',
  'rihlah_ruhiya','rida_wa_sakina','dhikr_wa_tasbih','sabr_wa_thabat'
];

const rotationIndex = ((dayIndex % ISLAMIC_CATEGORIES.length) + ISLAMIC_CATEGORIES.length) % ISLAMIC_CATEGORIES.length;
const category = ISLAMIC_CATEGORIES[rotationIndex];
const jobId = 'job_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8);

return [{
  json: {
    job_id: jobId,
    trigger_source: 'schedule',
    category,
    category_rotation_index: rotationIndex,
    day_index: dayIndex,
    publish_slot: 'night',
    publish_mode: 'auto_publish',
    scheduled_publish_hour: PUBLISH_HOUR,
    scheduled_date: localDate,
    scheduled_time: `${String(PUBLISH_HOUR).padStart(2,'0')}:00`,
    custom_topic: '',
    has_custom_topic: false,
    triggered_at_utc: nowUtc.toISOString(),
    triggered_local_date: localDate,
    hour_triggered_local: localHour,
    timezone_offset_used: TIMEZONE_OFFSET_HOURS,
    is_expected_window: Math.abs(localHour - PUBLISH_HOUR) <= 2,
    video_duration_seconds: 17,
    video_duration_min: 15,
    video_duration_max: 20,
    aspect_ratio: '9:16',
    render_model: 'kling-1-5',
    production_mode: 'image_to_video'
  }
}];

// ============================================================
// NODE: Smart Classifier — Islamic Shorts (Kling-1.5)
// ============================================================

const rows       = $('Get Ideas (ideas sheet)').all();
const configRows = $('Get Config (config sheet)').all();
const trigger    = $('Trigger Normalizer').first().json;

const config = {};
configRows.forEach(r => {
  const key = r.json.key || r.json.A;
  const val = r.json.value || r.json.B;
  if (key) config[key] = val;
});

const CHARACTER_IMAGE_URL = config['character_image_url'] || 'https://YOUR_DRIVE_URL/character_nour.jpg';

const CAT = {
  tamal_qurani: {
    label: 'تامل قراني',
    keywords: ['قرآن','آية','تدبر','تلاوة','حفظ'],
    bestTime: '21:00', ytCat: '22',
    hookStyle: 'فتاة محجبة وقورة تجلس في مكان هادئ وتتامل في آية قرآنية مع إضاءة خافتة دافئة',
    fallbackIdea: 'فتاة محجبة تجلس في غرفة هادئة مضاءة بنور خافت وتتامل في آية قرآنية عن الوقت'
  },
  tamal_kawni: {
    label: 'تامل كوني',
    keywords: ['كون','سماء','نجوم','فجر','خلق','طبيعة'],
    bestTime: '21:00', ytCat: '22',
    hookStyle: 'فتاة محجبة تنظر إلى السماء او الطبيعة في تامل عميق يربطها بالخالق',
    fallbackIdea: 'فتاة محجبة تقف عند نافذة قديمة في الفجر وتنظر إلى النجوم وهي تغيب'
  },
  muraqabat_nafs: {
    label: 'مراقبة النفس',
    keywords: ['محاسبة','مراقبة','نفس','ضمير','خلوة','صمت'],
    bestTime: '21:00', ytCat: '22',
    hookStyle: 'فتاة محجبة في خلوة هادئة تكتب او تتامل في احوال نفسها',
    fallbackIdea: 'فتاة محجبة تكتب في دفتر يدوي على ضوء مصباح صغير في محاسبة هادئة'
  },
  ilm_wa_marifa: {
    label: 'علم ومعرفة',
    keywords: ['علم','كتاب','مكتبة','قراءة','معرفة'],
    bestTime: '21:00', ytCat: '22',
    hookStyle: 'فتاة محجبة تقرا في كتاب قديم او تتامل في مكتبة مضاءة',
    fallbackIdea: 'فتاة محجبة تقف امام رف كتب ضخم وتمسك كتابا قديما بحنان واجلال'
  },
  rihlah_ruhiya: {
    label: 'رحلة روحية',
    keywords: ['سفر','طريق','رحلة','غربة','وجهة'],
    bestTime: '21:00', ytCat: '22',
    hookStyle: 'فتاة محجبة تسير في طريق يرمز إلى رحلة الروح نحو الله',
    fallbackIdea: 'فتاة محجبة تمشي في ممر طويل مضاء بضوء الغروب وظلها يمتد خلفها'
  },
  rida_wa_sakina: {
    label: 'رضا وسكينة',
    keywords: ['رضا','سكينة','قبول','اطمئنان','هدوء'],
    bestTime: '21:00', ytCat: '22',
    hookStyle: 'فتاة محجبة في سكينة تامة مع فنجان شاي او مطر في هدوء',
    fallbackIdea: 'فتاة محجبة تحمل كوب شاي دافئ وتنظر إلى المطر من خلف زجاج في رضا وقبول'
  },
  dhikr_wa_tasbih: {
    label: 'ذكر وتسبيح',
    keywords: ['ذكر','تسبيح','مسبحة','دعاء','قلب'],
    bestTime: '21:00', ytCat: '22',
    hookStyle: 'فتاة محجبة في ذكر خاشع تحرك شفتيها وقلبها حاضر',
    fallbackIdea: 'فتاة محجبة تمسك مسبحة خشبية في ضوء خافت وعيناها مغمضتان في ذكر عميق'
  },
  sabr_wa_thabat: {
    label: 'صبر وثبات',
    keywords: ['صبر','ثبات','ابتلاء','تحمل','دموع'],
    bestTime: '21:00', ytCat: '22',
    hookStyle: 'فتاة محجبة تعبر عن الصبر الحقيقي: الوقوف رغم البكاء',
    fallbackIdea: 'فتاة محجبة تمسح دموعها بهدوء ثم تاخذ نفسا عميقا وتنهض بثبات'
  }
};

const qualityThreshold = parseInt(config['quality_threshold'] || '8', 10);
const LOCK_ROTATION    = String(config['lock_category_rotation'] || 'false') === 'true';

let resolved = trigger.category;
if (!CAT[resolved]) resolved = 'tamal_qurani';
let cfgToday = CAT[resolved];

const available = rows.filter(r => {
  const s = String(r.json.production_status || '').toLowerCase().trim();
  return s !== 'completed' && s !== 'in_progress' && s !== 'rejected';
});

const recentCompleted = new Set(
  rows.filter(r => String(r.json.production_status || '').toLowerCase() === 'completed')
      .map(r => String(r.json.id || '').trim()).filter(Boolean)
);

function catScore(row) {
  const rowCat = String(row.json.category || '').toLowerCase().trim();
  if (rowCat === resolved) return 100;
  if (LOCK_ROTATION && CAT[rowCat] && rowCat !== resolved) return 0;
  const text = (row.json.idea || '').toLowerCase();
  const hits = cfgToday.keywords.filter(k => text.includes(k)).length;
  return hits >= 1 ? 50 + hits : 0;
}

let pool = available.map(r => ({ row: r, sc: catScore(r) })).filter(o => o.sc > 0);
let forceFallback = pool.length === 0;

if (!forceFallback) {
  const fresh = pool.filter(o => !recentCompleted.has(String(o.row.json.id || '').trim()));
  if (fresh.length > 0) pool = fresh; else forceFallback = true;
}

let rescueUsed = false;
if (forceFallback && !LOCK_ROTATION) {
  const anyFresh = available.filter(r => {
    const id  = String(r.json.id || '').trim();
    const cat = String(r.json.category || '').toLowerCase().trim();
    return CAT[cat] && !recentCompleted.has(id) && String(r.json.idea || '').trim();
  });
  if (anyFresh.length > 0) {
    const picked = anyFresh[Math.floor(Math.random() * anyFresh.length)];
    resolved = String(picked.json.category).toLowerCase().trim();
    cfgToday = CAT[resolved];
    pool = [{ row: picked, sc: 100 }];
    forceFallback = false;
    rescueUsed = true;
  }
}

let isAutoFallback = false, sel;

if (forceFallback || pool.length === 0) {
  isAutoFallback = true;
  sel = { json: { id: 'auto_' + Date.now(), idea: cfgToday.fallbackIdea, category: resolved } };
} else {
  pool.sort((a, b) => b.sc - a.sc);
  sel = pool[Math.floor(Math.random() * Math.min(3, pool.length))].row;
}

if (!sel || !String(sel.json.idea || '').trim()) {
  isAutoFallback = true;
  sel = { json: { id: 'auto_' + Date.now(), idea: cfgToday.fallbackIdea, category: resolved } };
}

const cfg        = CAT[resolved] || CAT['tamal_qurani'];
const finalTopic = trigger.custom_topic || sel.json.idea || cfg.label;

return [{
  json: {
    ...trigger,
    idea_id: String(sel.json.id || 'auto'),
    idea: sel.json.idea || '',
    final_topic: finalTopic,
    category: resolved,
    category_label: cfg.label,
    hook_style: cfg.hookStyle,
    yt_category_id: cfg.ytCat,
    best_publish_time: cfg.bestTime,
    quality_threshold: qualityThreshold,
    kling_prompt_hint: sel.json.kling_prompt || '',
    is_auto_fallback: isAutoFallback,
    rescue_pass_used: rescueUsed,
    pool_size: pool.length,
    available_count: available.length,
    rotation_locked: LOCK_ROTATION,
    video_duration_seconds: 17,
    video_duration_min: 15,
    video_duration_max: 20,
    aspect_ratio: '9:16',
    render_model: 'kling-1-5',
    production_mode: 'image_to_video',
    character_image_url: CHARACTER_IMAGE_URL,
    character_name: 'نور',
    classified_at: new Date().toISOString()
  }
}];

// ============================================================
// NODE: Parse AI Output — Islamic Shorts / Kling-1.5
// ============================================================

const classData = $('Smart Classifier').first().json;
const aiItem    = $input.first().json;

let raw = aiItem.output ?? aiItem.text ?? aiItem.message?.content ?? aiItem.choices?.[0]?.message?.content ?? '';
if (typeof raw !== 'string') raw = JSON.stringify(raw);

raw = raw.replace(/^\uFEFF/, '').replace(/```json/gi, '').replace(/```/g, '').replace(/[\u201C\u201D]/g, '"').trim();
const firstBrace = raw.indexOf('{');
const lastBrace  = raw.lastIndexOf('}');
if (firstBrace !== -1 && lastBrace > firstBrace) raw = raw.slice(firstBrace, lastBrace + 1);

let p = {}, parseError = '';
try { p = JSON.parse(raw); } catch (e1) {
  try { p = JSON.parse(raw.replace(/,\s*([}\]])/g, '$1').replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '')); }
  catch (e2) { parseError = String(e2.message || e2); p = {}; }
}

// Kling prompt
let klingPrompt = String(p.kling_prompt || '').trim();
if (/[\u0600-\u06FF]/.test(klingPrompt)) klingPrompt = klingPrompt.replace(/[\u0600-\u06FF]+/g, ' ').replace(/\s+/g, ' ').trim();
const kLower = klingPrompt.toLowerCase();
const missing = [];
if (!kLower.includes('9:16')) missing.push('9:16 vertical');
if (!kLower.includes('veiled') && !kLower.includes('hijab')) missing.push('veiled Arab woman');
if (missing.length) klingPrompt += ' Must include: ' + missing.join(', ') + '.';
if (klingPrompt.length > 1500) klingPrompt = klingPrompt.slice(0, 1497) + '...';

// Voiceover
const voiceover   = String(p.voiceover_arabic || '').trim();
const wordCount   = voiceover.split(/\s+/).filter(Boolean).length;
const voiceoverOk = wordCount >= 20 && wordCount <= 50;
// Title (70-80 chars, no emojis)
let title = String(p.youtube_title || '').trim().replace(/[\u{1F000}-\u{1FFFF}\u{2600}-\u{27FF}]/gu, '').trim();
const titleLen = [...title].length;

// Description (no emojis)
let desc = String(p.youtube_description || '').trim().replace(/[\u{1F000}-\u{1FFFF}\u{2600}-\u{27FF}]/gu, '').trim();

// Hashtags (12, no emojis)
const BLOCKED = new Set(['suicide','selfharm','nude','porn','sex','drug','gun','violence','bloody','gore']);
let baseTags  = Array.isArray(p.hashtags) ? p.hashtags : String(p.hashtags || '').split(/\s+/);
baseTags = baseTags
  .map(t => String(t).trim().replace(/[\u{1F000}-\u{1FFFF}\u{2600}-\u{27FF}]/gu,'').trim())
  .filter(Boolean)
  .map(t => t.startsWith('#') ? t : '#' + t)
  .filter(t => /^#[\w\u0600-\u06FF]+$/.test(t))
  .filter(t => !BLOCKED.has(t.replace('#','').toLowerCase()));

const fallbackTags = ['#إسلاميات','#تدبر','#IslamicContent','#ArabicShorts','#IslamicPhilosophy','#MuslimShorts','#DeepThinking','#SpiritualContent','#QuranReflection','#IslamicWisdom','#FaithContent','#محتوى_إسلامي'];
const uniqueTags   = [...new Set([...baseTags, ...fallbackTags])].slice(0, 12);

let score = Number(p.quality_score);
if (!Number.isFinite(score)) score = 8;
score = Math.max(1, Math.min(10, Math.round(score)));

const required     = ['topic','youtube_title','youtube_description','kling_prompt','voiceover_arabic'];
const missingFields= required.filter(f => !p[f] || String(p[f]).trim() === '');
const isValid      = parseError === '' && missingFields.length === 0 && klingPrompt.length > 80;

return [{
  json: {
    ...classData, ...p,
    category: classData.category,
    kling_prompt: klingPrompt,
    seedance_prompt: klingPrompt,
    voiceover_arabic: voiceover,
    youtube_title: title,
    youtube_description: desc,
    hashtags: uniqueTags,
    tags_clean: uniqueTags.map(t => t.replace('#','')),
    quality_score: score,
    is_valid: isValid,
    parse_error: parseError,
    missing_fields: missingFields,
    title_length: titleLen,
    title_length_ok: titleLen >= 65 && titleLen <= 85,
    voiceover_word_count: wordCount,
    voiceover_ok: voiceoverOk,
    hashtags_count: uniqueTags.length,
    render_model: 'kling-1-5',
    parsed_at: new Date().toISOString()
  }
}];

// ============================================================
// NODE: Pre-Publish Builder — Wan Speech-to-Video
// ============================================================

const parseData = $('Parse Gemini Output').first().json;
const classData = $('Smart Classifier').first().json;
const videoBinary = $('Download Video').first().binary;

if (!videoBinary?.video_data) {
  throw new Error('Final video binary not found. Expected: Download Video → video_data');
}

const data = {
  ...parseData,
  yt_category_id: parseData.yt_category_id || classData.yt_category_id || '22',
  category_label: parseData.category_label || classData.category_label || '',
  job_id: parseData.job_id || classData.job_id || '',
  final_topic: parseData.final_topic || classData.final_topic || '',
  quality_score: parseData.quality_score || 0,
};

// Title
let title = String(
  parseData.youtube_title ||
  data.final_topic ||
  'حين يصمت القلب تتكلم الروح'
).trim();

title = title
  .replace(/[\u{1F000}-\u{1FFFF}\u{2600}-\u{27FF}]/gu, '')
  .trim();

if ([...title].length > 80) {
  title = [...title].slice(0, 77).join('').trim() + '...';
}

// Hashtags
let finalTags = Array.isArray(parseData.hashtags)
  ? parseData.hashtags
  : String(parseData.hashtags || '').split(/\s+/);

finalTags = finalTags
  .map(tag => String(tag)
    .trim()
    .replace(/[\u{1F000}-\u{1FFFF}\u{2600}-\u{27FF}]/gu, '')
    .trim()
  )
  .filter(Boolean)
  .map(tag => tag.startsWith('#') ? tag : '#' + tag)
  .filter(tag => /^#[\w\u0600-\u06FF]+$/.test(tag));

finalTags = [...new Set(finalTags)].slice(0, 12);

const cleanTags = finalTags.map(tag => tag.replace('#', ''));
const hashBlock = finalTags.join(' ');

// Description
let baseDesc = String(parseData.youtube_description || '').trim();

baseDesc = baseDesc
  .replace(/[\u{1F000}-\u{1FFFF}\u{2600}-\u{27FF}]/gu, '')
  .trim();

const finalDescription = [
  baseDesc,
  '',
  hashBlock,
  '',
  'اشترك للمزيد من الفيديوهات الإسلامية الفكرية والتأملية.',
  'محتوى مرئي بالذكاء الاصطناعي لأغراض التدبر والتفكر.'
].join('\n');

// Scheduling
const TIMEZONE_OFFSET_HOURS = 3;

const now = new Date();
const localNow = new Date(
  now.getTime() + TIMEZONE_OFFSET_HOURS * 60 * 60 * 1000
);

const publishAt = new Date(localNow);
publishAt.setUTCHours(21, 0, 0, 0);

if (publishAt <= localNow) {
  publishAt.setUTCDate(publishAt.getUTCDate() + 1);
}

const publishAtUtc = new Date(
  publishAt.getTime() - TIMEZONE_OFFSET_HOURS * 60 * 60 * 1000
);

// Voiceover statistics
const voiceover = String(parseData.voiceover_arabic || '');
const voiceWords = voiceover.split(/\s+/).filter(Boolean).length;

return [{
  json: {
    ...data,
    final_title: title,
    final_description: finalDescription,
    final_tags: finalTags,
    clean_tags: cleanTags,
    scheduled_publish_at: publishAtUtc.toISOString(),

    qa_summary: {
      title_chars: [...title].length,
      hashtags_count: finalTags.length,
      quality_score: parseData.quality_score,
      category: data.category_label || parseData.category,
      render_model: 'wan/2-2-a14b-speech-to-video-turbo',
      production_mode: 'speech_to_video',
      audio_source: 'elevenlabs/text-to-dialogue-v3',
      voiceover_words: voiceWords,
      voiceover_ok: voiceWords >= 28 && voiceWords <= 48,
      video_synced: true
    }
  },

  binary: videoBinary
}];

// ============================================================
// Parse New Ideas
// يتحقق من 3 أفكار إسلامية قبل حفظها في شيت ideas
// ============================================================

const aiResponse = $input.first().json;
const brief = $('Build Rolling Idea Bank Brief').first().json;
const sheetRows = $('Get Ideas (ideas sheet)').all().map(item => item.json || {});

// استخراج الرد من Agent
let raw =
  aiResponse.output ??
  aiResponse.text ??
  aiResponse.message?.content ??
  aiResponse.choices?.[0]?.message?.content ??
  '';

if (typeof raw !== 'string') {
  raw = JSON.stringify(raw);
}

let clean = raw
  .replace(/^\uFEFF/, '')
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .replace(/[\u201C\u201D]/g, '"')
  .trim();

let generatedIdeas = [];
let parseError = '';

try {
  const match = clean.match(/\[[\s\S]*\]/);

  if (!match) {
    throw new Error('No JSON array found in AI response');
  }

  generatedIdeas = JSON.parse(match[0]);

  if (!Array.isArray(generatedIdeas)) {
    throw new Error('Response is not an array');
  }
} catch (error) {
  parseError = String(error.message || error);
  generatedIdeas = [];
}

// تنظيف النص العربي للمقارنة
function normalizeArabic(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/[\u064B-\u065F\u0670]/g, '')
    .replace(/[أإآ]/g, 'ا')
    .replace(/ة/g, 'ه')
    .replace(/ى/g, 'ي')
    .replace(/[^\u0600-\u06FFa-z0-9\s]/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const STOP_WORDS = new Set([
  'في', 'من', 'الى', 'إلى', 'عن', 'على', 'مع', 'هذا', 'هذه',
  'ذلك', 'تلك', 'التي', 'الذي', 'أن', 'ان', 'لا', 'ما', 'ثم',
  'قد', 'كان', 'تكون', 'ليس', 'كل', 'حين', 'عند', 'بعد', 'قبل',
  'هو', 'هي', 'كما', 'لكن', 'لعل', 'بين', 'حتى', 'أو', 'و'
]);

function meaningfulTokens(value) {
  return [...new Set(
    normalizeArabic(value)
      .split(/\s+/)
      .filter(token => token.length >= 3)
      .filter(token => !STOP_WORDS.has(token))
  )];
}

function similarityScore(a, b) {
  const tokensA = meaningfulTokens(a);
  const tokensB = meaningfulTokens(b);

  if (!tokensA.length || !tokensB.length) return 0;

  const setA = new Set(tokensA);
  const setB = new Set(tokensB);

  let intersection = 0;

  for (const token of setA) {
    if (setB.has(token)) intersection++;
  }

  const union = new Set([...setA, ...setB]).size;

  return union ? intersection / union : 0;
}

function isTooSimilar(candidate, previous) {
  const candidateNormalized = normalizeArabic(candidate);
  const previousNormalized = normalizeArabic(previous);

  if (!candidateNormalized || !previousNormalized) return false;

  if (candidateNormalized === previousNormalized) return true;

  const score = similarityScore(candidate, previous);

  return score >= 0.62;
}

function cleanText(value) {
  return String(value || '')
    .replace(/[\u{1F000}-\u{1FFFF}\u{2600}-\u{27FF}]/gu, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function isValidArabicIdea(value) {
  const text = cleanText(value);

  return (
    text.length >= 100 &&
    /[\u0600-\u06FF]/.test(text)
  );
}

function isValidPrompt(value) {
  const text = cleanText(value);

  const forbidden = /cctv|rescue|accident|gore|blood|violence|weapon|crime|crowd|subtitle|watermark|extra people/i;

  return (
    text.length >= 120 &&
    !/[\u0600-\u06FF]/.test(text) &&
    !forbidden.test(text) &&
    /9:16/i.test(text) &&
    /veiled|hijab/i.test(text) &&
    /lips/i.test(text)
  );
}

function getFutureDate(daysAhead) {
  const date = new Date();
  date.setUTCDate(date.getUTCDate() + daysAhead);
  return date.toISOString().slice(0, 10);
}

// الخطة التي حددتها عقدة Build Rolling Idea Bank Brief
const categoryPlan = Array.isArray(brief.category_plan)
  ? brief.category_plan
  : [];

if (categoryPlan.length !== 3) {
  throw new Error('Invalid category plan. Expected exactly 3 categories.');
}

// جميع الأفكار السابقة، مرتبة حسب الفئة
const previousByCategory = {};

for (const row of sheetRows) {
  const category = cleanText(row.category);
  const idea = cleanText(row.idea);

  if (!category || !idea) continue;

  if (!previousByCategory[category]) {
    previousByCategory[category] = [];
  }

  previousByCategory[category].push(idea);
}

// نستخدم كل الأفكار السابقة لمنع التكرار
const acceptedIdeasByCategory = {};

const output = [];
const timestamp = Date.now();

for (let index = 0; index < categoryPlan.length; index++) {
  const plan = categoryPlan[index];

  // نبحث عن العنصر المطابق للفئة المطلوبة
  const candidate = generatedIdeas.find(item => {
    return cleanText(item.category) === plan.id;
  });

  if (!candidate) {
    continue;
  }

  const idea = cleanText(candidate.idea);
  const visualPrompt = cleanText(candidate.kling_prompt);
  const angle = cleanText(candidate.angle);

  // تحقق من جودة الفكرة
  if (!isValidArabicIdea(idea)) {
    continue;
  }

  // تحقق من جودة Visual Prompt
  if (!isValidPrompt(visualPrompt)) {
    continue;
  }

  const oldIdeas = previousByCategory[plan.id] || [];
  const acceptedInSameCategory = acceptedIdeasByCategory[plan.id] || [];

  const duplicatedWithOld = oldIdeas.some(oldIdea => {
    return isTooSimilar(idea, oldIdea);
  });

  const duplicatedInBatch = acceptedInSameCategory.some(newIdea => {
    return isTooSimilar(idea, newIdea);
  });

  // لا نضيف الفكرة إن كانت متكررة أو قريبة جدًا
  if (duplicatedWithOld || duplicatedInBatch) {
    continue;
  }

  if (!acceptedIdeasByCategory[plan.id]) {
    acceptedIdeasByCategory[plan.id] = [];
  }

  acceptedIdeasByCategory[plan.id].push(idea);

  let priority = cleanText(candidate.priority).toLowerCase();

  if (!['high', 'medium'].includes(priority)) {
    priority = 'medium';
  }

  output.push({
    json: {
      id: `auto_rolling_${timestamp}_${index + 1}`,

      idea,
      category: plan.id,

      production_status: 'pending',
      priority,

      // الفكرة الأولى تحتاج غالبًا غدًا، الثانية بعد غد، الثالثة بعده
      scheduled_date: getFutureDate(index + 1),
      scheduled_time: '21:00',

      // اسم العمود يبقى kling_prompt لتوافق الشيت والكود القديم
      kling_prompt: visualPrompt,

      youtube_title: '',
      hashtags: '',

      notes: [
        'auto-generated rolling idea bank',
        `angle=${angle || plan.required_angle || 'not_specified'}`,
        `category=${plan.id}`,
        `parseError=${parseError || 'none'}`
      ].join(' | ')
    }
  });
}

return output;

// Extract Audio URL — ElevenLabs via Google Drive
const driveUpload = $('Google Drive Audio Upload').first().json;
const fileId = driveUpload.id;
if (!fileId) throw new Error('Google Drive Audio Upload: file id not found.');
const audioUrl = `https://drive.google.com/uc?export=download&id=${fileId}`;
const parseData = $('Parse Gemini Output').first().json;
return [{ json: { ...parseData, audio_url: audioUrl, audio_ready: true,
  audio_ready_at: new Date().toISOString(), drive_audio_file_id: fileId } }];

