// ============================================================
// NODE: Increment Poll Count — Wan Speech2Video
// يحسب عدد المحاولات ويحدد حالة المهمة
// ============================================================

const input = $input.first().json;

// Carry through original idea context from Extract Audio URL
let ideaContext = {};
try {
  ideaContext = $('Extract Audio URL').first().json;
} catch (e) {}

const pollCount = $runIndex + 1;
const MAX_POLLS = 240;

const data = input.data || {};
const state = data.successFlag ?? data.state ?? data.status ?? 'pending';

const isSuccess = 
  state === 1 || 
  state === '1' ||
  String(state).toLowerCase() === 'success' ||
  String(state).toLowerCase() === 'succeed' ||
  String(state).toLowerCase() === 'completed';

const isFailed = 
  state === 2 || 
  state === 3 || 
  state === '2' || 
  state === '3' ||
  String(state).toLowerCase() === 'failed' ||
  String(state).toLowerCase() === 'fail' ||
  String(state).toLowerCase() === 'error' ||
  String(state).toLowerCase() === 'timeout';

const isTimeout = pollCount > MAX_POLLS;

let statusReason = 'pending';
if (isTimeout)      statusReason = 'timeout_exceeded_max_polls';
else if (isSuccess) statusReason = 'success';
else if (isFailed)  statusReason = data.failMsg || data.fail_reason || 'failed';

console.log(`[Poll ${pollCount}/${MAX_POLLS}] State: ${state} | Success: ${isSuccess} | Failed: ${isFailed || isTimeout}`);

return [{
  json: {
    ...ideaContext,
    ...input,
    _poll_count: pollCount,
    max_polls: MAX_POLLS,
    current_state: state,
    is_success: isSuccess,
    is_failed: isFailed || isTimeout,
    is_pending: !isSuccess && !isFailed && !isTimeout,
    status_reason: statusReason,
    elapsed_seconds: pollCount * 5
  }
}];

// ============================================================
// NODE: Extract Video URL — Wan 2.2 Speech-to-Video
// يستخرج رابط الفيديو النهائي من ناتج KIE
// ============================================================

const raw = $input.first().json;

// 1. فحص الفشل أولاً
if (raw.is_failed) {
  throw new Error(`Video generation failed after ${raw.elapsed_seconds}s. Reason: ${raw.status_reason}`);
}

const data = raw.data || raw;

// 2. محاولة قراءة resultJson (قد يكون string أو object)
let resultJson = data.resultJson || data;
if (typeof resultJson === 'string') {
  try { resultJson = JSON.parse(resultJson); } catch (e) {}
}

// 3. البحث عن رابط الفيديو في كل المواقع الممكنة
const candidates = [
  // المسار الأكثر شيوعاً لـ KIE
    resultJson?.data?.resultUrls,
  resultJson?.resultUrls,
  data?.resultUrls,
  resultJson?.data?.result_urls,
  resultJson?.result_urls,
  data?.result_urls,
  // مسارات بديلة
  [resultJson?.data?.video_url],
  [resultJson?.video_url],
  [data?.videoUrl],
  [data?.video_url],
  [data?.url],
  // مسار Wan الخاص
  resultJson?.data?.output?.video_url,
  resultJson?.output?.video_url,
  // مسار array مسطح
  resultJson?.data?.urls,
  resultJson?.urls
];

let videoUrl = null;

for (const candidate of candidates) {
  if (!candidate) continue;

  // إذا كان array
  if (Array.isArray(candidate) && candidate.length > 0) {
    const url = String(candidate[0]).trim();
    if (url.startsWith('http')) {
      videoUrl = url;
      break;
    }
  }

  // إذا كان string مباشر
  if (typeof candidate === 'string' && candidate.startsWith('http')) {
    videoUrl = candidate.trim();
    break;
  }
}

// 4. إذا لم نجد رابطاً، نرمي خطأ مع تفاصيل للاستكشاف
if (!videoUrl) {
  const debugInfo = JSON.stringify({
    data_keys: Object.keys(data),
    resultJson_keys: typeof resultJson === 'object' ? Object.keys(resultJson) : 'not_object',
    successFlag: data.successFlag,
    state: data.state
  }).slice(0, 800);

  throw new Error(`No video URL found in KIE response. Debug: ${debugInfo}`);
}

// 5. جمع البيانات من العقد السابقة
const parseData = $('Parse Gemini Output').first().json;
const classData = $('Smart Classifier').first().json;
const taskId = $('KIE — Create Wan Speech2Video').first().json.data?.taskId;

return [{
  json: {
    ...parseData,
    ...classData,
    video_url: videoUrl,
    kie_task_id: taskId,
    video_ready_at: new Date().toISOString(),
    render_model: 'wan-2-2-speech-to-video',
    total_generation_seconds: raw.elapsed_seconds || 0,
    poll_count: raw._poll_count || 0
  }
}];

// ============================================================
// NODE: Check Audio Status
// يتأكد هل مهمة ElevenLabs عبر KIE اكتملت أو ما زالت تعمل
// ============================================================

const raw = $input.first().json;
const data = raw.data && typeof raw.data === 'object'
  ? raw.data
  : {};

// KIE قد يعيد الحالة بأسماء مختلفة حسب النموذج
const state =
  data.successFlag ??
  data.state ??
  data.status ??
  raw.successFlag ??
  raw.state ??
  raw.status ??
  'pending';

const normalizedState = String(state).trim().toLowerCase();

// عدد مرات تشغيل هذه العقدة ضمن الحلقة
const pollCount = $runIndex + 1;

// 20 × 15 ثانية = حوالي 5 دقائق كحد أقصى
const MAX_AUDIO_POLLS = 60;
const successStates = [
  '1',
  'success',
  'succeed',
  'succeeded',
  'completed',
  'complete',
  'finished',
  'done'
];

const failedStates = [
  '2',
  '3',
  'failed',
  'fail',
  'error',
  'timeout',
  'cancelled',
  'canceled'
];

const isAudioSuccess =
  state === 1 ||
  state === '1' ||
  successStates.includes(normalizedState);

const isAudioFailedByApi =
  state === 2 ||
  state === 3 ||
  state === '2' ||
  state === '3' ||
  failedStates.includes(normalizedState);

const isAudioTimeout = pollCount >= MAX_AUDIO_POLLS;

const isAudioFailed = isAudioFailedByApi || isAudioTimeout;

const failureReason =
  data.failMsg ||
  data.fail_reason ||
  data.errorMessage ||
  data.error ||
  (isAudioTimeout
    ? `Audio timeout after ${MAX_AUDIO_POLLS} polls`
    : '');

return [{
  json: {
    ...raw,

    audio_poll_count: pollCount,
    audio_max_polls: MAX_AUDIO_POLLS,
audio_elapsed_seconds: pollCount * 5,
    audio_state: state,
    audio_state_normalized: normalizedState,

    is_audio_success: isAudioSuccess,
    is_audio_failed: isAudioFailed,
    is_audio_pending: !isAudioSuccess && !isAudioFailed,

    audio_failure_reason: failureReason || 'pending'
  }
}];

// ============================================================
// Build Rolling Idea Bank Brief
// نظام اقتصادي: يولد 3 أفكار فقط عند فراغ أفكار الأيام القادمة
// ============================================================

const classifier = $('Smart Classifier').first().json;
const sheetRows = $('Get Ideas (ideas sheet)').all().map(item => item.json || {});

// دورة التصنيفات الأساسية
const CATEGORIES = [
