      'كيف تكشف الخلوة حقيقة القلب'
    ]
  },
  {
    id: 'ilm_wa_marifa',
    label: 'علم ومعرفة',
    angles: [
      'المعرفة التي تجعل الإنسان أكثر تواضعًا',
      'الفرق بين كثرة المعلومات وعمق الفهم',
      'العلم الذي يهدئ العقل بدل أن يثقله',
      'السؤال الصادق بوصفه بداية معرفة',
      'التأمل قبل الحكم السريع',
