      'كيف يصبح التأمل طريقًا لا لحظة'
    ]
  },
  {
    id: 'rida_wa_sakina',
    label: 'رضا وسكينة',
    angles: [
      'الرضا حين تتأخر الإجابة',
      'السكينة وسط ما لا نستطيع تفسيره',
      'قبول ما لا نملك تغييره',
      'الفرق بين الاستسلام والرضا',
      'الهدوء بعد الفقد أو الخيبة',
      'كيف يتخفف القلب من مقاومة الواقع',
