const blockedStatuses = new Set([
  'completed',
  'in_progress',
  'rejected',
  'failed',
  'skipped'
]);

function text(value) {
  return String(value || '').trim();
}

function isReadyIdea(row) {
  const status = text(row.production_status).toLowerCase();

  return (
    text(row.idea).length > 20 &&
    !blockedStatuses.has(status)
  );
}

