const futureStats = nextThreeCategories.map(category => {
  const allCategoryIdeas = sheetRows.filter(row => {
    return text(row.category) === category.id;
  });

  const readyIdeas = allCategoryIdeas.filter(isReadyIdea);

  return {
    id: category.id,
    label: category.label,
    readyCount: readyIdeas.length,
    totalHistoryCount: allCategoryIdeas.filter(row => text(row.idea)).length,
    angles: category.angles
  };
});

