// لا يستدعي OpenAI إلا إذا لم توجد ولا فكرة واحدة
// للتصنيفات الثلاثة القادمة.
const shouldGenerate = coveredFutureCategories === 0;

// إذا لدينا مخزون ولو بسيط، لا نرسل أي Item للعقدة التالية.
// هذا يعني أن Auto Idea Generator لن يعمل ولن يستهلك رصيدًا.
if (!shouldGenerate) {
  return [];
}

// تجهيز 3 فئات + 3 زوايا مختلفة
const categoryPlan = futureStats.map((item, index) => {
  const angleIndex = item.totalHistoryCount % item.angles.length;
  const selectedAngle = item.angles[angleIndex];

  return {
    order: index + 1,
    id: item.id,
    label: item.label,
    required_angle: selectedAngle
  };
});

// نرسل فقط آخر 8 أفكار من كل تصنيف لتقليل Tokens
const previousIdeasForPrompt = categoryPlan.map(plan => {
  const ideas = sheetRows
    .filter(row => text(row.category) === plan.id && text(row.idea))
    .slice(-8)
    .map((row, index) => {
      return `${index + 1}. ${text(row.idea).slice(0, 350)}`;
    });

  return [
    `CATEGORY: ${plan.id} — ${plan.label}`,
    ideas.length ? ideas.join('\n') : 'No previous ideas stored for this category.'
  ].join('\n');
}).join('\n\n---\n\n').slice(0, 6500);

const categoryPlanText = categoryPlan.map(plan => {
  return [
    `${plan.order}. category: ${plan.id}`,
    `Arabic label: ${plan.label}`,
    `Required fresh philosophical angle: ${plan.required_angle}`
  ].join(' | ');
}).join('\n');

return [{
  json: {
    should_generate: true,
    generation_mode: 'rolling_3_day_buffer',
    generation_count: 3,

    generated_at: new Date().toISOString(),
    source_job_id: classifier.job_id,

    current_category: classifier.category,
    current_category_label: classifier.category_label,

    category_plan: categoryPlan,
    category_plan_text: categoryPlanText,

    previous_ideas_text: previousIdeasForPrompt,

    coverage_before_generation: {
      next_categories: futureStats.map(item => ({
        category: item.id,
        ready_ideas: item.readyCount
      })),
      covered_future_categories: coveredFutureCategories
    }
  }
}];
